import{_ as e,o as i,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"CDS Jewel -- CephX brute-force protection","description":"","frontmatter":{"title":"CDS Jewel -- CephX brute-force protection","date":"2015-08-03T00:00:00.000Z","updated":"2015-08-04T00:00:00.000Z","tags":["Ceph 安全","暴力破解保护","黑名单机制","认证安全","日志记录"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Jewel_--_CephX_brute-force_protection.md","filePath":"posts/2015/CDS_Jewel_--_CephX_brute-force_protection.md","lastUpdated":1780459816000}'),r={name:"posts/2015/CDS_Jewel_--_CephX_brute-force_protection.md"};function p(_,l,s,n,a,c){return i(),t("div",null,[...l[0]||(l[0]=[o("<p>会议纪要：</p><p><strong>会议主题</strong>： 安全讨论，特别是关于CephX暴力破解保护和安全措施。</p><p><strong>关键细节</strong>：</p><ul><li><strong>讨论背景</strong>： 近几个月与Sage关于Ceph安全性的讨论。</li><li><strong>主要议题</strong>： <ul><li>如何检测和防止系统内的暴力破解尝试，特别是针对CephX认证。</li><li>实现自动黑名单机制，针对频繁尝试错误认证的用户。</li><li>如何识别攻击者，是否使用IP地址或TCP连接。</li><li>是否应该在集群启动时或在系统重启时实施黑名单机制。</li><li>考虑在系统重启时或在系统运行一段时间后实施黑名单机制，并设置过期时间。</li><li>是否应该将管理网络与公共网络隔离。</li><li>监视器是否应该对OSD映射进行签名，以增强安全性。</li></ul></li><li><strong>决定的事项</strong>： <ul><li>优先处理黑名单机制的实现，包括改进日志记录，检测错误认证尝试，实现自动黑名单机制，识别攻击者。</li><li>对管理网络进行隔离的讨论暂时搁置，因为可能会带来额外的复杂性而收益有限。</li><li>考虑对OSD映射进行签名，以提高安全性。</li></ul></li><li><strong>后续行动计划</strong>： <ul><li>研究和实现黑名单机制。</li><li>研究如何识别攻击者，并确定使用IP地址或TCP连接。</li><li>研究在系统重启时或在系统运行一段时间后实施黑名单机制。</li><li>考虑对OSD映射进行签名。</li></ul></li></ul><p><strong>关键词</strong>：</p><ul><li>暴力破解</li><li>黑名单</li><li>日志记录</li><li>认证</li><li>攻击者</li><li>Ceph</li><li>CephX</li><li>黑名单机制</li><li>OSD映射</li><li>签名</li></ul>",6)])])}const g=e(r,[["render",p]]);export{C as __pageData,g as default};
